import buildingsJson from './buildings.json';
import iconsJson from './icons.json';
import itemsJson from './items.json';
import recipesJson from './recipes.json';
import transportJson from './transport.json';
import type { Building, Item, Recipe, Transport } from './game-data.model';

/** Typed views over the JSON generated by `npm run data:extract`. */
export const ITEMS = itemsJson as Item[];
export const BUILDINGS = buildingsJson as Building[];
export const RECIPES = recipesJson as Recipe[];
export const TRANSPORT = transportJson as Transport[];

/** IDs with an icon in public/icons, generated by `npm run icons:extract`. */
export const ICON_IDS: ReadonlySet<string> = new Set(iconsJson as string[]);
